INSERT INTO public.hit_report_modules (id, category, title, content) VALUES
('ONB-ORG-H', 'onboarding', '조직 적응 — 빠르게 자리 잡는 힘', '새 조직의 규칙과 분위기를 빠르게 읽고 맞춰 가는 힘이 있습니다. 입사 첫 달의 낯섦이 짧게 지나갈 가능성이 큽니다. 다만 빨리 적응하려다 내 의견을 너무 아끼지 않도록, 석 달 안에 작은 제안 하나는 꼭 해 보세요.'),
('ONB-ORG-M', 'onboarding', '조직 적응 — 무난하게 적응', '새 환경에 큰 어려움 없이 적응할 수 있습니다. 첫 달에는 일하는 방식과 보고 체계를 관찰하고, 모르는 것은 정리해서 한 번에 묻는 습관을 들이세요. 입사 전에 회사의 최근 소식과 조직 문화를 알아 두면 적응이 훨씬 빨라집니다.'),
('ONB-ORG-L', 'onboarding', '조직 적응 — 미리 준비하면 편해짐', '새 조직의 규칙과 분위기가 부담스럽게 느껴질 수 있습니다. 적응은 성격보다 준비의 문제인 경우가 많습니다. 입사 전에 회사의 일하는 방식을 알아보고, 첫 2주 동안 물어볼 것을 미리 적어 두세요. 인턴·대외활동으로 조직 경험을 한 번 쌓아 두는 것도 큰 도움이 됩니다.'),
('ONB-LEARN-H', 'onboarding', '학습 속도 — 빠르게 익히는 힘', '업무를 빠르게 익히는 힘이 강점입니다. 신입 시기에 가장 크게 인정받는 부분입니다. 배운 것을 나만의 업무 노트로 정리해 두면, 몇 달 뒤 후배에게 알려 줄 수 있을 만큼 탄탄해집니다.'),
('ONB-LEARN-M', 'onboarding', '학습 속도 — 배우면 해냄', '배우면 해낼 수 있습니다. 처음에는 속도가 느리게 느껴질 수 있지만, 배운 것을 바로 메모하고 다음 날 한 번 다시 보는 습관만으로도 속도가 크게 올라갑니다. 직무에 자주 쓰는 도구 하나를 입사 전에 미리 익혀 두세요.'),
('ONB-LEARN-L', 'onboarding', '학습 속도 — 작게 쪼개면 빨라짐', '새 업무를 익히는 데 시간이 걸릴 수 있습니다. 괜찮습니다 — 방법을 바꾸면 달라집니다. 큰 업무를 작은 단계로 나눠 하나씩 익히고, 모르는 것을 모아 두었다가 한 번에 묻는 방식을 써 보세요. 희망 직무의 기본 도구를 미리 실습해 두면 출발선이 앞당겨집니다.'),
('ONB-REL-H', 'onboarding', '관계 형성 — 빠르게 신뢰를 쌓는 힘', '동료·선배와 빠르게 신뢰를 쌓는 힘이 있습니다. 좋은 관계는 정보와 기회를 함께 가져옵니다. 넓게 사귀는 것만큼, 내 성장을 도와줄 선배 한 명과 깊이 이어지는 관계도 만들어 보세요.'),
('ONB-REL-M', 'onboarding', '관계 형성 — 무난하게 관계를 맺음', '관계를 무난하게 만들 수 있습니다. 먼저 인사하고, 점심이나 짧은 대화를 제안하는 작은 시도가 큰 차이를 만듭니다. 도움을 받으면 결과를 짧게라도 알려 주세요 — 신뢰가 빠르게 쌓입니다.'),
('ONB-REL-L', 'onboarding', '관계 형성 — 한 사람부터', '먼저 다가가는 것이 어렵게 느껴질 수 있습니다. 모두와 친해질 필요는 없습니다. 한 사람과 깊이 친해지는 것부터 목표로 하세요. 동아리·스터디 같은 작은 모임에서 관계를 이어 가는 연습이 회사에서도 그대로 도움이 됩니다.'),
('ONB-FEEDBACK-H', 'onboarding', '피드백 수용 — 성장의 재료로 쓰는 힘', '지적과 조언을 성장의 재료로 쓰는 힘이 강점입니다. 이 힘이 있으면 같은 시간에 남보다 빨리 자랍니다. 받은 피드백을 다음 결과물에 반영했는지 스스로 확인하고, 반영한 결과를 피드백 준 사람에게 알려 주세요.'),
('ONB-FEEDBACK-M', 'onboarding', '피드백 수용 — 받아들일 수 있음', '피드백을 받아들일 수 있습니다. 다만 표현에 따라 마음이 쓰이는 때가 있을 수 있습니다. 피드백을 받으면 "무엇을 바꾸면 될까요?"라고 구체적으로 되물어 보세요. 감정보다 다음 행동에 집중하게 됩니다.'),
('ONB-FEEDBACK-L', 'onboarding', '피드백 수용 — 묻는 연습부터', '피드백이 상처나 평가로 느껴질 수 있습니다. 피드백은 나에 대한 판단이 아니라 결과물에 대한 의견입니다. 작은 과제부터 먼저 "어떤 점을 고치면 좋을까요?"라고 묻는 연습을 해 보세요. 스스로 요청한 피드백은 훨씬 편하게 들립니다.'),
('DEC-H', 'career_decision', '진로 결정 — 방향이 분명함', '가고 싶은 직무를 분명히, 내 판단으로 정했습니다. 방향이 분명하면 준비에 힘을 모을 수 있습니다. 이제 필요한 것은 그 선택을 경험으로 확인하는 일입니다 — 인턴·프로젝트로 직접 해 보고, 결정이 맞는지 점검해 보세요.'),
('DEC-M', 'career_decision', '진로 결정 — 방향은 있고 확신은 더 필요', '방향은 정했지만 아직 확신이 단단하지는 않습니다. 자연스러운 단계입니다. 희망 직무의 현직자 한 명을 만나 하루 일과를 들어 보고, 작은 프로젝트로 직접 해 보세요. 해 본 경험이 확신을 만듭니다.'),
('DEC-L', 'career_decision', '진로 결정 — 아직 고르는 중', '아직 방향을 고르는 중입니다. 서두르지 않아도 됩니다. HIT - Archetype의 흥미와 HIT - Bounce의 "중심에 둘 분야"를 함께 보고 후보를 두세 개로 좁혀 보세요. 후보마다 작은 경험(강의 하나, 현직자 대화 하나)을 해 보면 방향이 선명해집니다.')
