-- HIT - Challenger 해설 — 첫 직무 적응 4영역 × 3단계 + 진로 결정 확신 3단계 = 15개 (2026-10-12, R3)
-- 단계: H 75+ · M 50~74 · L 50 미만 (화면 구간과 같음)
-- 선택: lib/hit/stage-report-modules.ts case 'c' → ONB-{ORG|LEARN|REL|FEEDBACK}-{H|M|L}, DEC-{H|M|L}
-- 재실행 가능. 롤백: DELETE FROM hit_report_modules WHERE id LIKE 'ONB-%' OR id LIKE 'DEC-%';

ON CONFLICT (id) DO UPDATE SET category = EXCLUDED.category, title = EXCLUDED.title, content = EXCLUDED.content, updated_at = now();
